     1	import type { Booking } from '@prisma/client';
     2	import { bookingConflict, notFound } from '../../shared/errors.js';
     3	import {
     4	  normalizeLimit,
     5	  normalizeOffset,
     6	  paginated,
     7	  type Page,
     8	} from '../../shared/pagination.js';
     9	import { parseInstant } from '../../shared/time.js';
    10	import * as repository from './repository.js';
    11	import { BOOKING_CANCELLED } from './schema.js';
    12	import type { CreateBookingInput, ListBookingsInput, UpdateBookingInput } from './schema.js';
    13	
    14	export async function createBooking(input: CreateBookingInput): Promise<Booking> {
    15	  const startsAt = parseInstant(input.startsAt);
    16	  const endsAt = parseInstant(input.endsAt);
    17	
    18	  const conflict = await repository.findConflictAtStart(input.roomId, startsAt);
    19	  if (conflict) {
    20	    throw bookingConflict(conflict.id);
    21	  }
    22	
    23	  return repository.create({
    24	    roomId: input.roomId,
    25	    userId: input.userId,
    26	    title: input.title,
    27	    startsAt,
    28	    endsAt,
    29	  });
    30	}
    31	
    32	export async function getBooking(id: string): Promise<Booking> {
    33	  const booking = await repository.findById(id);
    34	  if (!booking) {
    35	    throw notFound('Booking');
    36	  }
    37	  return booking;
    38	}
    39	
    40	export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
    41	  const limit = normalizeLimit(query.limit);
    42	  const offset = normalizeOffset(query.offset);
    43	  const [data, total] = await repository.list({
    44	    roomId: query.roomId,
    45	    userId: query.userId,
    46	    status: query.status,
    47	    from: query.from ? parseInstant(query.from) : undefined,
    48	    to: query.to ? parseInstant(query.to) : undefined,
    49	    limit,
    50	    offset,
    51	  });
    52	  return paginated(data, total, limit, offset);
    53	}
    54	
    55	export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
    56	  await getBooking(id);
    57	  return repository.update(id, {
    58	    ...(input.roomId !== undefined ? { roomId: input.roomId } : {}),
    59	    ...(input.userId !== undefined ? { userId: input.userId } : {}),
    60	    ...(input.title !== undefined ? { title: input.title } : {}),
    61	    ...(input.startsAt !== undefined ? { startsAt: parseInstant(input.startsAt) } : {}),
    62	    ...(input.endsAt !== undefined ? { endsAt: parseInstant(input.endsAt) } : {}),
    63	  });
    64	}
    65	
    66	export async function cancelBooking(id: string): Promise<Booking> {
    67	  const booking = await getBooking(id);
    68	  if (booking.status === BOOKING_CANCELLED) {
    69	    return booking;
    70	  }
    71	  return repository.updateStatus(id, BOOKING_CANCELLED);
    72	}
    73	
    74	export async function deleteBooking(id: string): Promise<void> {
    75	  await getBooking(id);
    76	  await repository.remove(id);
    77	}

