     2	import { Type } from '@sinclair/typebox';
     3	import { replyConflict, replyNotFound } from '../../shared/http-reply.js';
     4	import * as queries from './queries.js';
     5	
     6	const AmenityResponse = Type.Object({
     7	  id: Type.String(),
     8	  name: Type.String(),
     9	  description: Type.Union([Type.String(), Type.Null()]),
    10	});
    11	
    12	const CreateAmenityBody = Type.Object(
    13	  {
    14	    name: Type.String({ minLength: 1, maxLength: 80 }),
    15	    description: Type.Optional(Type.String({ maxLength: 200 })),
    16	  },
    17	  { additionalProperties: false },
    18	);
    19	
    20	const AmenityIdParams = Type.Object({ id: Type.String({ minLength: 1 }) });
    21	
    22	const RoomAmenityParams = Type.Object({
    23	  roomId: Type.String({ minLength: 1 }),
    24	  amenityId: Type.String({ minLength: 1 }),
    25	});
    26	
    27	export const amenitiesRoutes: FastifyPluginAsyncTypebox = async (app) => {
    28	  app.post('/amenities', { schema: { body: CreateAmenityBody, response: { 201: AmenityResponse } } },
    29	    async (request, reply) => {
    30	      const existing = await queries.findAmenityByName(request.body.name);
    31	      if (existing) {
    32	        return replyConflict(reply, 'AMENITY_NAME_TAKEN', 'Amenity name is already in use');
    33	      }
    34	      const created = await queries.insertAmenity(request.body.name, request.body.description);
    35	      return reply.code(201).send(created);
    36	    });
    37	
    38	  app.get('/amenities', { schema: { response: { 200: Type.Array(AmenityResponse) } } },
    39	    async () => queries.listAmenities());
    40	
    41	  app.delete('/amenities/:id', { schema: { params: AmenityIdParams } },
    42	    async (request, reply) => {
    43	      const amenity = await queries.findAmenityById(request.params.id);
    44	      if (!amenity) {
    45	        return replyNotFound(reply, 'Amenity');
    46	      }
    47	      await queries.deleteAmenity(amenity.id);
    48	      return reply.code(204).send();
    49	    });
    50	
    51	  app.put('/rooms/:roomId/amenities/:amenityId', { schema: { params: RoomAmenityParams } },
    52	    async (request, reply) => {
    53	      const room = await queries.findRoom(request.params.roomId);
    54	      if (!room) {
    55	        return replyNotFound(reply, 'Room');
    56	      }
    57	      const amenity = await queries.findAmenityById(request.params.amenityId);
    58	      if (!amenity) {
    59	        return replyNotFound(reply, 'Amenity');
    60	      }
    61	      await queries.linkAmenity(room.id, amenity.id);
    62	      return reply.code(204).send();
    63	    });
    64	
    65	  app.delete('/rooms/:roomId/amenities/:amenityId', { schema: { params: RoomAmenityParams } },
    66	    async (request, reply) => {
