import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { createTestApp, resetDb } from '../app/tests/helpers/app.js';

const HOUR = 3_600_000;
const inHours = (h: number) => new Date(Date.now() + h * HOUR).toISOString();

describe('probe', () => {
  let app: FastifyInstance; let roomId: string; let userId: string;
  beforeAll(async () => { app = await createTestApp(); });
  afterAll(async () => { await app.close(); });
  beforeEach(async () => {
    await resetDb();
    roomId = (await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })).json().id;
    userId = (await app.inject({ method: 'POST', url: '/users', payload: { name: 'Ada', email: 'a@e.com' } })).json().id;
  });
  const book = (s: number, e: number, t = 'Sync', extra: Record<string, unknown> = {}) =>
    app.inject({ method: 'POST', url: '/bookings', payload: { roomId, userId, title: t, startsAt: inHours(s), endsAt: inHours(e), ...extra } });

  it('P1 new starts before existing, ends inside', async () => {
    await book(24, 25);
    const r = await book(23.5, 24.5, 'Front overlap');
    console.log('P1', r.statusCode, r.body);
  });
  it('P2 new contains existing', async () => {
    await book(24, 25);
    const r = await book(23, 26, 'Envelope');
    console.log('P2', r.statusCode, r.body);
  });
  it('P3 identical interval', async () => {
    await book(24, 25);
    const r = await book(24, 25, 'Same');
    console.log('P3', r.statusCode, r.body);
  });
  it('P4 end before start', async () => {
    const r = await book(25, 24, 'Backwards');
    console.log('P4', r.statusCode, r.body);
  });
  it('P5 zero length', async () => {
    const r = await book(24, 24, 'Zero');
    console.log('P5', r.statusCode, r.body);
  });
  it('P6 unknown room', async () => {
    const r = await app.inject({ method: 'POST', url: '/bookings', payload: { roomId: 'nope', userId, title: 'X', startsAt: inHours(24), endsAt: inHours(25) } });
    console.log('P6', r.statusCode, r.body);
  });
  it('P7 unknown user', async () => {
    const r = await app.inject({ method: 'POST', url: '/bookings', payload: { roomId, userId: 'nope', title: 'X', startsAt: inHours(24), endsAt: inHours(25) } });
    console.log('P7', r.statusCode, r.body);
  });
  it('P8 patch onto an occupied slot', async () => {
    await book(24, 25);
    const b = await book(30, 31, 'Move me');
    const r = await app.inject({ method: 'PATCH', url: `/bookings/${b.json().id}`, payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) } });
    console.log('P8', r.statusCode, r.body);
  });
  it('P9 patch to backwards range', async () => {
    const b = await book(24, 25);
    const r = await app.inject({ method: 'PATCH', url: `/bookings/${b.json().id}`, payload: { endsAt: inHours(23) } });
    console.log('P9', r.statusCode, r.body);
  });
  it('P10 patch to unknown room', async () => {
    const b = await book(24, 25);
    const r = await app.inject({ method: 'PATCH', url: `/bookings/${b.json().id}`, payload: { roomId: 'nope' } });
    console.log('P10', r.statusCode, r.body);
  });
  it('P11 junk instant that Date accepts', async () => {
    const r = await app.inject({ method: 'POST', url: '/bookings', payload: { roomId, userId, title: 'X', startsAt: '5', endsAt: '2030' } });
    console.log('P11', r.statusCode, r.body);
  });
  it('P12 past booking', async () => {
    const r = await book(-5, -4, 'Past');
    console.log('P12', r.statusCode, r.body);
  });
  it('P13 concurrent identical bookings', async () => {
    const [a, b] = await Promise.all([book(40, 41, 'A'), book(40, 41, 'B')]);
    console.log('P13', a.statusCode, b.statusCode);
  });
});
EOF
