import type { Booking, Prisma } from '@prisma/client';
import { prisma } from '../../db/client.js';
import { BOOKING_ACTIVE } from './schema.js';

export type Tx = Prisma.TransactionClient;

export interface BookingData {
  roomId: string;
  userId: string;
  title: string;
  startsAt: Date;
  endsAt: Date;
}

export interface BookingFilter {
  roomId?: string;
  userId?: string;
  status?: string;
  from?: Date;
  to?: Date;
  limit: number;
  offset: number;
}

export interface OverlapQuery {
  roomId: string;
  startsAt: Date;
  endsAt: Date;
  excludeBookingId?: string;
}

/**
 * Runs the conflict check and the write that depends on it inside a single
 * transaction, so two requests for the same slot cannot both pass the check.
 */
export function transaction<T>(fn: (tx: Tx) => Promise<T>): Promise<T> {
  return prisma.$transaction(fn);
}

export function create(data: BookingData, client: Tx = prisma): Promise<Booking> {
  return client.booking.create({ data });
}

/**
 * Finds an active booking of the same room whose period overlaps [startsAt, endsAt).
 * Two periods overlap when each one starts before the other ends, which also
 * covers a period that contains or is contained by the other. Bookings that
 * merely touch at the edges (one ends exactly when the next starts) do not.
 */
export function findOverlapping(query: OverlapQuery, client: Tx = prisma): Promise<Booking | null> {
  return client.booking.findFirst({
    where: {
      roomId: query.roomId,
      status: BOOKING_ACTIVE,
      startsAt: { lt: query.endsAt },
      endsAt: { gt: query.startsAt },
      ...(query.excludeBookingId ? { id: { not: query.excludeBookingId } } : {}),
    },
    orderBy: { startsAt: 'asc' },
  });
}

export function findById(id: string): Promise<Booking | null> {
  return prisma.booking.findUnique({ where: { id } });
}

export async function roomExists(id: string): Promise<boolean> {
  return (await prisma.room.findUnique({ where: { id }, select: { id: true } })) !== null;
}

export async function userExists(id: string): Promise<boolean> {
  return (await prisma.user.findUnique({ where: { id }, select: { id: true } })) !== null;
}

export function list(filter: BookingFilter): Promise<[Booking[], number]> {
  const where: Prisma.BookingWhereInput = {};
  if (filter.roomId) where.roomId = filter.roomId;
  if (filter.userId) where.userId = filter.userId;
  if (filter.status) where.status = filter.status;
  if (filter.from) where.startsAt = { gte: filter.from };
  if (filter.to) where.endsAt = { lte: filter.to };

  return prisma.$transaction([
    prisma.booking.findMany({
      where,
      take: filter.limit,
      skip: filter.offset,
      orderBy: { startsAt: 'asc' },
    }),
    prisma.booking.count({ where }),
  ]);
}

export function update(id: string, data: Partial<BookingData>, client: Tx = prisma): Promise<Booking> {
  return client.booking.update({ where: { id }, data });
}

export function updateStatus(id: string, status: string): Promise<Booking> {
  return prisma.booking.update({ where: { id }, data: { status } });
}

export function remove(id: string): Promise<Booking> {
  return prisma.booking.delete({ where: { id } });
}
